// Owner question set 2 (V1.15), part E: Spring Boot, beans and lifecycle, AOP and transactions, REST and API security.
import { kp, Q } from './kp.js';

const SB = 'Spring Boot', SF = 'Spring Framework', REST = 'REST & API Design', SEC = 'Security';
const src = { source: 'owner-set2' };

export const V115_E = [
  // ---------------------------------------------------------------- 13. Spring Framework and Spring Boot
  Q('nq-175', SB, 'E', 'concept', 'Why do you use Spring Boot, and what does it add on top of the Spring Framework?',
    [kp('Auto-configuration based on classpath', 'auto configuration', 'auto-configuration', 'classpath'), kp('Starter dependencies with compatible versions', 'starter*', 'dependency management', 'versions'), kp('Embedded server, runnable fat jar', 'embedded', 'tomcat', 'fat jar', 'executable jar'), kp('Externalised configuration and profiles', 'application.yml', 'application.properties', 'profile*', 'external*'), kp('Production features: Actuator, metrics, health', 'actuator', 'metrics', 'health')],
    'Spring Framework gives dependency injection, MVC, data access, transactions and much more, but on its own you had to configure a lot: XML or Java config, a servlet container, matching library versions. Spring Boot is an opinionated layer on top that removes that work. Auto-configuration sets up beans based on what is on the classpath and your properties; starters bring curated, compatible dependency sets; an embedded Tomcat, Jetty or Undertow lets you run the app as a single executable jar with java -jar; externalised configuration with application.yml, profiles and environment variables suits containers; and Actuator gives health, metrics and info endpoints. So we get from zero to a production-ready service much faster, and can still override any default.',
    'How would you see which auto-configurations were applied?', src),
  Q('nq-176', SB, 'EM', 'concept', 'What are the main advantages and disadvantages of Spring Boot?',
    [kp('Advantages: fast setup, auto-config, starters, embedded server, actuator', 'fast', 'auto config*', 'starter*', 'embedded', 'actuator'), kp('Large ecosystem and community; cloud/microservice ready', 'ecosystem', 'community', 'microservice*', 'cloud'), kp('Disadvantages: hidden magic, harder debugging of auto-config', 'magic', 'hidden', 'debug*'), kp('Larger footprint, startup time and memory', 'memory', 'startup', 'footprint', 'jar size'), kp('Mitigations: native images/GraalVM, conditions report, lazy init', 'graalvm', 'native image', 'conditions report', 'lazy')],
    'Advantages: very fast project setup with Spring Initializr; auto-configuration and starters remove boilerplate and version conflicts; an embedded server and single jar make deployment and containers easy; externalised configuration and profiles; production readiness with Actuator and Micrometer; and a huge ecosystem: Spring Data, Security, Cloud, Kafka. Disadvantages: the auto-configuration magic hides what is happening, so problems such as an unexpected bean or a missing DataSource can be hard to debug; starters pull in many dependencies, increasing jar size, memory use and startup time; and it is opinionated. Mitigations include the --debug conditions report, excluding auto-configurations, lazy initialisation, and GraalVM native images or CRaC for fast startup.',
    'How would you reduce Spring Boot startup time?', src),
  Q('nq-177', SB, 'M', 'concept', 'What is auto-configuration in Spring Boot?',
    [kp('Configuration classes applied automatically based on conditions', 'conditions', 'conditional*', 'automatic*'), kp('Loaded from META-INF/spring/...AutoConfiguration.imports (spring.factories before)', 'autoconfiguration.imports', 'spring.factories', 'meta-inf'), kp('@EnableAutoConfiguration via @SpringBootApplication', 'enableautoconfiguration', 'springbootapplication'), kp('Backs off when you define your own bean (@ConditionalOnMissingBean)', 'back off', 'backs off', 'conditionalonmissingbean', 'your own bean'), kp('Debug with --debug / conditions report; exclude', '--debug', 'conditions report', 'exclude')],
    '@SpringBootApplication includes @EnableAutoConfiguration, which imports all auto-configuration classes listed in META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports of each jar, spring.factories in older versions. Each is an ordinary @Configuration guarded by conditions: @ConditionalOnClass, so DataSourceAutoConfiguration only applies if a JDBC driver and DataSource classes are present; @ConditionalOnProperty for feature flags; and @ConditionalOnMissingBean, so if you define your own bean, Boot backs off. They read settings from @ConfigurationProperties classes bound to application.yml. You can inspect decisions with --debug or the Actuator conditions endpoint, and switch some off with exclude on @SpringBootApplication.',
    'How would you write your own auto-configuration for a shared library?', { ...src, sameAs: 'java-025' }),
  Q('nq-178', SB, 'E', 'concept', 'What are Spring Boot starter dependencies?',
    [kp('Curated dependency descriptors for a capability', 'curated', 'dependency', 'capability', 'one dependency'), kp('Examples web, data-jpa, security, test, actuator', 'starter-web', 'data-jpa', 'starter-security', 'starter-test', 'actuator'), kp('Versions managed by the Boot parent/BOM', 'bom', 'parent', 'version*'), kp('Trigger related auto-configuration', 'auto configuration', 'auto-configuration')],
    'A starter is a dependency that bundles everything needed for one capability, with versions that are tested together. spring-boot-starter-web brings Spring MVC, Jackson, validation and embedded Tomcat; spring-boot-starter-data-jpa brings Spring Data JPA, Hibernate and HikariCP; spring-boot-starter-security, starter-actuator and starter-test with JUnit 5, Mockito and AssertJ are other examples. You do not specify versions, because the Spring Boot parent POM or BOM manages them, which avoids conflicts. Adding a starter also puts classes on the classpath that trigger the matching auto-configuration.',
    'How do you replace Tomcat with Jetty in a web starter?', src),
  Q('nq-179', SB, 'E', 'concept', 'What is the purpose of an embedded Tomcat server?',
    [kp('Server runs inside the application process', 'inside', 'embedded', 'same process'), kp('No separate server install or WAR deployment; java -jar', 'no separate', 'war', 'java -jar'), kp('Ideal for containers and microservices; config via server.* properties', 'container*', 'docker', 'microservice*', 'server.port'), kp('Swap for Jetty/Undertow/Netty', 'jetty', 'undertow', 'netty')],
    'With an embedded server, Tomcat is a library inside your application, started by Spring Boot when the app starts, rather than a separately installed server into which you deploy WAR files. The whole service is one executable jar started with java -jar, carrying its own server version and configuration through properties like server.port, server.tomcat.threads.max or SSL settings. That makes each microservice self-contained, easy to put in a Docker image, scale horizontally, and avoids conflicts between applications sharing one server. You can replace Tomcat with Jetty or Undertow by swapping starters, and WebFlux uses Netty.',
    'When might you still deploy a WAR to an external server?', src),
  Q('nq-180', SB, 'EM', 'concept', 'What is Spring Boot Actuator, and what information does it expose?',
    [kp('Production-ready monitoring and management endpoints', 'monitoring', 'management', 'endpoint*'), kp('health (liveness/readiness), info, metrics, prometheus', 'health', 'metrics', 'prometheus', 'liveness', 'readiness'), kp('env, beans, mappings, loggers, threaddump, heapdump, conditions', 'env', 'beans', 'mappings', 'loggers', 'threaddump'), kp('Exposure controlled by management.endpoints.web.exposure.include', 'exposure', 'management.endpoints'), kp('Secure sensitive endpoints; separate management port', 'secur*', 'management port', 'sensitive')],
    'Actuator adds production-ready endpoints for monitoring and managing a running application, under /actuator. Health shows the status of the app and its dependencies, such as the database, disk and Kafka, with liveness and readiness groups for Kubernetes probes. Info shows build and git information; metrics and prometheus expose Micrometer metrics like JVM memory, GC, HTTP request timings and connection pools. Diagnostic endpoints include env, configprops, beans, mappings, conditions, loggers, where you can change log levels at runtime, threaddump and heapdump. By default only health is exposed over HTTP; you enable others with management.endpoints.web.exposure.include, and you must secure them because env and heapdump reveal sensitive data.',
    'How do Kubernetes probes use Actuator health groups?', src),
  Q('nq-181', SB, 'M', 'concept', 'What are conditional beans in Spring Boot?',
    [kp('Beans registered only if a condition is met', 'only if', 'condition*', 'registered'), kp('@Conditional with a Condition class; Boot convenience annotations', '@conditional', 'condition class', 'conditionalon*'), kp('Based on properties, classes, beans, profiles, environment', 'propert*', 'class*', 'bean*', 'profile'), kp('Used by auto-configuration and feature toggles', 'auto configuration', 'auto-configuration', 'feature toggle*', 'feature flag*')],
    'Conditional beans are bean definitions that Spring registers only when some condition holds at startup. The core mechanism is @Conditional(MyCondition.class), where the Condition implementation inspects the environment. Spring Boot adds convenient ones: @ConditionalOnProperty, @ConditionalOnClass and @ConditionalOnMissingClass, @ConditionalOnBean and @ConditionalOnMissingBean, @ConditionalOnWebApplication, @ConditionalOnExpression, plus @Profile. Auto-configuration is built from them, and you can use them for feature toggles, choosing between implementations per environment, for example a real SMS sender in production and a logging stub elsewhere, or providing defaults in shared libraries.',
    'Why is @ConditionalOnBean ordering-sensitive in normal configuration classes?', src),
  Q('nq-182', SB, 'M', 'concept', 'What are @ConditionalOnProperty, @ConditionalOnClass, and @ConditionalOnMissingBean?',
    [kp('@ConditionalOnProperty: based on a property value, havingValue, matchIfMissing', 'conditionalonproperty', 'havingvalue', 'matchifmissing', 'property'), kp('@ConditionalOnClass: when a class is on the classpath', 'conditionalonclass', 'classpath'), kp('@ConditionalOnMissingBean: only if no bean of that type exists (defaults that back off)', 'conditionalonmissingbean', 'no bean', 'default', 'back off'), kp('Examples for each', 'example*', 'feature', 'redis', 'datasource')],
    '@ConditionalOnProperty(name = "payments.mock.enabled", havingValue = "true", matchIfMissing = false) registers the bean only when the property has that value, which is ideal for feature flags and environment-specific beans. @ConditionalOnClass(name = "io.lettuce.core.RedisClient") registers it only if that class is on the classpath, so a library can offer Redis support only when the user added the Redis driver. @ConditionalOnMissingBean(CacheManager.class) registers a default bean only if the application has not defined its own, so user configuration wins. Auto-configurations combine all three: present library, enabled property, and no user-defined bean.',
    'Why is @ConditionalOnMissingBean usually placed on auto-configuration rather than application config?', src),
  Q('nq-183', SB, 'MS', 'scenario', 'How would you create beans conditionally for different microservices?',
    [kp('Use properties per service and @ConditionalOnProperty', 'conditionalonproperty', 'property', 'per service'), kp('Profiles for environment differences', 'profile*'), kp('Shared library auto-configuration with conditions and @ConditionalOnMissingBean defaults', 'shared library', 'auto configuration', 'conditionalonmissingbean'), kp('@ConditionalOnClass to activate only when dependency present', 'conditionalonclass', 'dependency'), kp('Externalised config (config server, env vars)', 'config server', 'environment variable*', 'external*')],
    'I keep the behaviour switchable through configuration rather than code branches. Beans that only some services need are guarded with @ConditionalOnProperty, for example audit.publisher.enabled=true in the order service but not in the catalogue service; environment differences use profiles; and support for an optional technology uses @ConditionalOnClass, so the Kafka-based publisher only activates in services that include the Kafka dependency. If these beans live in a shared library, I package them as an auto-configuration with @ConditionalOnMissingBean defaults, so any service can override with its own bean. Properties come from each service application.yml, a config server or environment variables in Kubernetes, and I test both enabled and disabled cases with ApplicationContextRunner.',
    'How would you test conditional configuration?', src),
  Q('nq-184', SB, 'SL', 'design', 'How can common utility libraries be shared across microservices while allowing service-specific functionality?',
    [kp('Publish a versioned library/custom starter to an artifact repository', 'library', 'starter', 'artifact*', 'nexus', 'artifactory', 'version*'), kp('Auto-configuration with conditional, overridable defaults', 'auto configuration', 'conditionalonmissingbean', 'override', 'default*'), kp('Extension points: interfaces, properties, customizer beans', 'interface*', 'customizer*', 'extension', 'hook*'), kp('Keep it small: cross-cutting only, no domain logic; avoid tight coupling', 'cross cutting', 'no domain', 'coupl*', 'small'), kp('Semantic versioning and backward compatibility', 'semantic version*', 'backward compat*')],
    'I would build a small, versioned internal library, ideally as a custom Spring Boot starter, published to Nexus or Artifactory, for truly cross-cutting concerns: logging and correlation ids, error response format, security filters, HTTP client setup, metrics tags. It uses auto-configuration with conditions, so features switch on by property and @ConditionalOnMissingBean lets a service replace any default bean. For service-specific behaviour I expose extension points: interfaces the service implements, customizer beans like RestClientCustomizer, and @ConfigurationProperties. I keep domain logic out of the shared library to avoid a distributed monolith, use semantic versioning, keep changes backward compatible, and let each service upgrade at its own pace.',
    'What are the risks of a shared library across many services?', src),
  Q('nq-185', SF, 'MS', 'concept', 'What is the role of Spring Framework 6 in modern Java applications?',
    [kp('Baseline Java 17 and Jakarta EE 9+ (javax -> jakarta)', 'java 17', 'jakarta', 'javax'), kp('Foundation for Spring Boot 3', 'spring boot 3'), kp('AOT processing and GraalVM native images', 'aot', 'graalvm', 'native image*'), kp('Observability with Micrometer, HTTP interface clients, RestClient, virtual threads support', 'micrometer', 'observability', 'http interface', 'restclient', 'virtual thread*'), kp('Problem Details (RFC 7807) error responses', 'problem detail*', 'rfc 7807', 'rfc 9457')],
    'Spring Framework 6, released in 2022, is the foundation of Spring Boot 3. It raised the baseline to Java 17 and moved from Java EE javax packages to Jakarta EE 9 and later jakarta packages, which is the main migration effort. It introduced ahead-of-time processing so applications can be compiled into GraalVM native images with fast startup and low memory; built-in observability through Micrometer Observation for metrics and tracing; declarative HTTP interface clients with @HttpExchange, and later the RestClient; RFC 7807 Problem Details for standard error responses; and support for virtual threads in 6.1. It keeps Spring current with modern Java, cloud and container deployments.',
    'What did you have to change when migrating to Spring Boot 3?', src),

  // ---------------------------------------------------------------- 14. Beans, lifecycle and scopes
  Q('nq-186', SF, 'E', 'concept', 'What are Spring beans?',
    [kp('Objects created and managed by the Spring IoC container', 'ioc container', 'managed', 'container'), kp('Defined via @Component/@Service/@Repository or @Bean', '@component', '@service', '@bean', 'stereotype'), kp('Dependencies injected (DI), lifecycle and scope handled by Spring', 'inject*', 'dependency injection', 'lifecycle', 'scope'), kp('Singleton by default', 'singleton')],
    'A Spring bean is an object whose creation, wiring and lifecycle are managed by the Spring IoC container, the ApplicationContext, instead of being created with new in your code. You declare beans with stereotype annotations such as @Component, @Service, @Repository and @Controller discovered by component scanning, or with @Bean methods in @Configuration classes. The container creates them, injects their dependencies, preferably through constructors, applies scope, singleton by default, runs lifecycle callbacks and can wrap them in proxies for transactions, security or caching.',
    'Why is constructor injection preferred?', src),
  Q('nq-187', SF, 'E', 'concept', 'What are the different bean scopes in Spring?',
    [kp('singleton (default): one per container', 'singleton'), kp('prototype: new instance each request from container', 'prototype'), kp('Web scopes: request, session, application, websocket', 'request', 'session', 'application', 'websocket'), kp('Declared with @Scope', '@scope'), kp('Injecting shorter-lived into singletons needs proxies/ObjectProvider', 'proxy', 'objectprovider', 'scoped proxy')],
    'Spring core has two scopes. Singleton, the default, means one shared instance per application context. Prototype means a new instance every time the bean is requested from the container. Web-aware contexts add request, one instance per HTTP request; session, one per HTTP session; application, one per ServletContext; and websocket, one per WebSocket session. You set it with @Scope("prototype") or @RequestScope. When a singleton depends on a shorter-lived bean, you need a scoped proxy or an ObjectProvider, otherwise the singleton keeps the first instance forever.',
    'What happens when a prototype bean is injected into a singleton?', src),
  Q('nq-188', SF, 'E', 'concept', 'What is the default bean scope?',
    [kp('Singleton', 'singleton'), kp('One instance per ApplicationContext, not per JVM', 'per application context', 'applicationcontext', 'not per jvm', 'container'), kp('Created eagerly at startup by default', 'eager*', 'startup'), kp('Must be stateless or thread-safe', 'stateless', 'thread safe', 'thread-safe')],
    'The default scope is singleton: the container creates one instance of the bean and injects that same instance everywhere. Note that it is one per ApplicationContext, unlike the GoF Singleton which is one per class loader. Singletons are created eagerly at startup unless marked @Lazy, which surfaces configuration errors early. Because one instance serves all concurrent requests, singleton beans such as services and controllers should be stateless, or keep only thread-safe state, never per-request data in fields.',
    'Why is storing request data in a field of a @Service a bug?', src),
  Q('nq-189', SF, 'M', 'concept', 'What is the difference between singleton and prototype scopes?',
    [kp('Singleton: one shared instance; prototype: new instance per lookup/injection', 'one shared', 'new instance', 'each time'), kp('Container manages full lifecycle of singletons; not destruction of prototypes', 'destroy', 'destruction', 'predestroy', 'lifecycle'), kp('Prototype injected into singleton is created only once', 'injected once', 'only once', 'singleton'), kp('Use ObjectProvider/lookup method/@Lookup to get fresh prototypes', 'objectprovider', 'lookup', '@lookup', 'provider')],
    'A singleton bean has one instance per context, created at startup and shared, and Spring manages its whole lifecycle including destruction callbacks on shutdown. A prototype bean gets a new instance each time it is requested from the container or injected into a new consumer; Spring creates and initialises it, but then hands it over and does not call destroy methods, so the client must clean up resources. A common trap: injecting a prototype into a singleton creates the prototype only once, at injection time. To get a fresh one each time, inject ObjectProvider<MyPrototype> and call getObject, use a @Lookup method, or a scoped proxy.',
    'Can you give a use case for prototype scope?', src),
  Q('nq-190', SF, 'M', 'concept', 'What is request scope?',
    [kp('One bean instance per HTTP request', 'per http request', 'per request', 'each request'), kp('@RequestScope / @Scope(WebApplicationContext.SCOPE_REQUEST)', '@requestscope', 'scope_request'), kp('Injected into singletons through a scoped proxy', 'proxy', 'scoped proxy', 'proxymode'), kp('Use: per-request context like user info, correlation id', 'correlation', 'user', 'context', 'tenant')],
    'A request-scoped bean lives for a single HTTP request: each request gets its own instance, and it is discarded when the request completes. You declare it with @RequestScope, which is @Scope("request") with proxyMode TARGET_CLASS. Because singletons are created once, Spring injects a proxy into them, and each method call on the proxy is routed to the instance bound to the current request thread. It is useful for per-request data such as the authenticated user context, tenant id, correlation id or a request-level cache. It only works inside a web request; using it from a background thread or a scheduled job fails with no thread-bound request found.',
    'Why do request-scoped beans fail inside @Async methods?', src),
  Q('nq-191', SF, 'M', 'concept', 'What are the different stages of the Spring bean lifecycle?',
    [kp('Instantiation, then dependency injection (populate properties)', 'instantiat*', 'inject*', 'populate'), kp('Aware callbacks: BeanNameAware, ApplicationContextAware', 'aware', 'beannameaware', 'applicationcontextaware'), kp('BeanPostProcessor before init, init (@PostConstruct, afterPropertiesSet, initMethod), after init (proxies)', 'beanpostprocessor', '@postconstruct', 'afterpropertiesset', 'init'), kp('Bean in use', 'in use', 'ready'), kp('Destruction: @PreDestroy, DisposableBean, destroyMethod', '@predestroy', 'disposablebean', 'destroy')],
    'For a singleton the stages are: the container reads the bean definition, possibly modified by BeanFactoryPostProcessors; it instantiates the bean through its constructor; populates dependencies through setters or fields; calls Aware interfaces such as BeanNameAware and ApplicationContextAware; runs BeanPostProcessor postProcessBeforeInitialization; calls initialisation callbacks, @PostConstruct, then InitializingBean.afterPropertiesSet, then a custom init method; runs postProcessAfterInitialization, where AOP proxies for @Transactional and similar are created; and then the bean is ready and in use. On context shutdown it calls @PreDestroy, DisposableBean.destroy and a custom destroy method.',
    'In which stage are @Transactional proxies created?', src),
  Q('nq-192', SF, 'MS', 'concept', 'What are BeanFactoryPostProcessor and BeanPostProcessor?',
    [kp('BeanFactoryPostProcessor modifies bean definitions before any bean is created', 'bean definition*', 'before', 'metadata'), kp('Example: PropertySourcesPlaceholderConfigurer resolving ${}', 'placeholder', 'propertysourcesplaceholderconfigurer'), kp('BeanPostProcessor modifies bean instances before/after initialisation', 'instance*', 'before initiali*', 'after initiali*'), kp('Example: AOP proxy creation, @Autowired processing', 'proxy', 'autowiredannotationbeanpostprocessor', 'aop')],
    'Both are container extension points but act at different times. A BeanFactoryPostProcessor runs after bean definitions are loaded and before any bean is instantiated; it works on the metadata, so it can change definitions, for example change scope or property values, or register new definitions. PropertySourcesPlaceholderConfigurer, which resolves placeholders, and ConfigurationClassPostProcessor are examples. A BeanPostProcessor runs for each bean instance, around initialisation: postProcessBeforeInitialization and postProcessAfterInitialization, and it may return a different object, which is how Spring wraps beans in proxies for AOP, transactions and async. AutowiredAnnotationBeanPostProcessor and CommonAnnotationBeanPostProcessor handle @Autowired and @PostConstruct.',
    'Why should a BeanFactoryPostProcessor @Bean method be static?', src),
  Q('nq-193', SF, 'M', 'concept', 'What callback interfaces are involved in the bean lifecycle?',
    [kp('InitializingBean.afterPropertiesSet and DisposableBean.destroy', 'initializingbean', 'afterpropertiesset', 'disposablebean'), kp('Aware interfaces: BeanNameAware, BeanFactoryAware, ApplicationContextAware', 'aware'), kp('Annotations @PostConstruct/@PreDestroy preferred', '@postconstruct', '@predestroy'), kp('@Bean(initMethod, destroyMethod); SmartLifecycle', 'initmethod', 'destroymethod', 'smartlifecycle', 'lifecycle')],
    'Lifecycle callbacks come in several forms. Interfaces: InitializingBean with afterPropertiesSet after dependencies are set, and DisposableBean with destroy on shutdown. Aware interfaces let a bean receive container objects: BeanNameAware, BeanClassLoaderAware, BeanFactoryAware, ApplicationContextAware, EnvironmentAware. Annotations: @PostConstruct and @PreDestroy from jakarta.annotation, which are the preferred approach because they do not couple code to Spring. Configuration: @Bean(initMethod = "start", destroyMethod = "close"), handy for third-party classes. For start and stop phases across beans, Lifecycle and SmartLifecycle with phases, and ApplicationListener for events like ContextRefreshedEvent or ApplicationReadyEvent.',
    'In what order are @PostConstruct, afterPropertiesSet and initMethod called?', src),
  Q('nq-194', SF, 'M', 'concept', 'What happens during bean initialization and destruction?',
    [kp('Initialisation after dependencies injected: validate, open resources, warm caches', 'after dependencies', 'validate', 'resources', 'warm'), kp('Order: @PostConstruct, afterPropertiesSet, init-method; then proxies', 'order', '@postconstruct', 'afterpropertiesset', 'init method'), kp('Destruction on context close: @PreDestroy, destroy(), destroy-method; release resources', 'context close', 'shutdown', 'release', '@predestroy'), kp('Prototype beans are not destroyed by the container', 'prototype'), kp('Graceful shutdown in Spring Boot', 'graceful shutdown')],
    'Initialisation happens after the bean is constructed and all dependencies are injected, so the bean can safely use them: validating configuration, opening connections, starting a scheduler or warming a cache. Callbacks run in this order: @PostConstruct, then afterPropertiesSet, then a custom init method, and afterwards BeanPostProcessors may wrap the bean in a proxy, so code inside @PostConstruct does not go through the proxy and @Transactional does not apply there. Destruction happens when the context closes, for example on application shutdown: @PreDestroy, then DisposableBean.destroy, then a custom destroy method, to close pools, flush buffers or deregister. Prototype beans are not destroyed by the container, and Spring Boot graceful shutdown lets in-flight requests finish first.',
    'Why should you avoid long-running work in @PostConstruct?', src),

  // ---------------------------------------------------------------- 15. AOP and transactions
  Q('nq-195', SF, 'EM', 'concept', 'What is aspect-oriented programming (AOP)?',
    [kp('Modularises cross-cutting concerns', 'cross cutting', 'cross-cutting', 'modulari*'), kp('Terms: aspect, advice, pointcut, join point, weaving', 'aspect', 'advice', 'pointcut', 'join point', 'weaving'), kp('Advice types: before, after, around, afterReturning, afterThrowing', 'before', 'after', 'around'), kp('Spring AOP proxy-based vs AspectJ weaving', 'proxy', 'aspectj')],
    'AOP is a programming paradigm that separates cross-cutting concerns, behaviour needed in many places such as logging, security, transactions, caching and metrics, from business logic, so you write it once in an aspect. Key terms: a join point is a point in execution, in Spring always a method call; a pointcut is an expression selecting join points, like execution(* com.acme.service.*.*(..)) or @annotation(Audited); advice is the code to run, before, after returning, after throwing, after or around; an aspect combines pointcuts and advice; weaving links aspects with targets. Spring AOP weaves at runtime with proxies, while AspectJ can weave at compile or load time and intercept more join points.',
    'What limitations does proxy-based Spring AOP have?', src),
  Q('nq-196', SF, 'M', 'scenario', 'What are cross-cutting concerns, and how can AOP be used for logging?',
    [kp('Concerns spread across many modules: logging, security, transactions, metrics', 'logging', 'security', 'transaction*', 'metric*', 'spread'), kp('@Aspect with @Around advice and a pointcut', '@aspect', '@around', 'pointcut'), kp('ProceedingJoinPoint.proceed, measure time, log args/results/exceptions', 'proceedingjoinpoint', 'proceed', 'execution time', 'duration'), kp('Custom annotation to target methods (e.g. @LogExecution)', 'custom annotation', 'annotation'), kp('Avoid logging sensitive data; overhead', 'sensitive', 'pii', 'overhead', 'personal data', 'passwords')],
    'Cross-cutting concerns are requirements that affect many classes but are not their core responsibility: logging, auditing, security checks, transactions, retries and metrics. Implemented by hand, they duplicate code everywhere. With Spring AOP I create a @Component @Aspect class with an @Around advice, for example @Around("@annotation(LogExecutionTime)") or a pointcut on all service methods. The advice receives a ProceedingJoinPoint, logs the method name and arguments, records the start time, calls proceed, logs the result or catches and logs the exception with its duration, and rethrows. Business methods stay clean, and the behaviour can be changed in one place. I take care not to log passwords or personal data and to keep the aspect lightweight.',
    'Why might the aspect not run for a method called from within the same class?', src),
  Q('nq-197', SF, 'M', 'concept', 'How does Spring AOP work through proxy objects?',
    [kp('Container wraps the target bean in a proxy at creation (BeanPostProcessor)', 'proxy', 'wrap*', 'beanpostprocessor', 'creation'), kp('Callers get the proxy; proxy runs advice then delegates to target', 'delegat*', 'advice', 'target'), kp('Only public method calls through the proxy are intercepted', 'public', 'external call*', 'through the proxy'), kp('Self-invocation bypasses the proxy', 'self invocation', 'self-invocation', 'this.'), kp('JDK dynamic proxy or CGLIB subclass', 'jdk', 'cglib')],
    'When a bean matches any pointcut, Spring does not inject the bean itself. During creation an auto-proxy BeanPostProcessor wraps it in a proxy that implements the same interfaces or subclasses its class, and that proxy is what other beans receive. When a caller invokes a method, the proxy runs the chain of advice that applies, for example opening a transaction or logging, then calls the real method on the target, and runs the remaining advice afterwards. Consequences: only calls coming through the proxy are intercepted, so a method calling another method of the same object with this bypasses the advice; final methods and, with CGLIB, final classes cannot be advised; and private methods are not intercepted.',
    'How can you work around self-invocation?', src),
  Q('nq-198', SF, 'MS', 'concept', 'What is the difference between JDK dynamic proxies and CGLIB proxies?',
    [kp('JDK proxy implements interfaces only (java.lang.reflect.Proxy)', 'interface*', 'java.lang.reflect.proxy', 'jdk'), kp('CGLIB creates a subclass of the target class at runtime', 'subclass', 'cglib', 'bytecode'), kp('CGLIB cannot proxy final classes/methods', 'final'), kp('Spring Boot defaults to CGLIB (proxyTargetClass=true)', 'proxytargetclass', 'default', 'spring boot'), kp('Injection by concrete class needs CGLIB', 'concrete class', 'class type')],
    'A JDK dynamic proxy, java.lang.reflect.Proxy, creates at runtime a class implementing the interfaces of the target and routes calls through an InvocationHandler, so it only works when the bean implements interfaces, and the proxy can only be injected by interface type. CGLIB generates a subclass of the target class at runtime with bytecode, overriding methods to add advice, so it works without interfaces and can be injected by concrete class, but it cannot proxy final classes or final methods, and the constructor considerations are handled by Objenesis. Spring Framework uses JDK proxies when interfaces exist, but Spring Boot sets proxyTargetClass to true, so CGLIB is the default there.',
    'What error do you get if you inject a JDK-proxied bean by its class?', src),
  Q('nq-199', SF, 'M', 'concept', 'How does transaction management work in Spring?',
    [kp('Declarative via @Transactional, or programmatic via TransactionTemplate', '@transactional', 'declarative', 'transactiontemplate', 'programmatic'), kp('PlatformTransactionManager abstraction (JPA, JDBC, Kafka)', 'platformtransactionmanager', 'transaction manager', 'jpatransactionmanager'), kp('Proxy begins, commits or rolls back around the method', 'proxy', 'begin', 'commit', 'roll* back'), kp('Propagation and isolation settings', 'propagation', 'isolation', 'requires_new'), kp('Connection bound to the thread (ThreadLocal)', 'thread', 'threadlocal', 'bound')],
    'Spring offers a consistent transaction abstraction, PlatformTransactionManager, with implementations for JDBC, JPA, JTA, Kafka and reactive drivers. Usually you use declarative transactions: annotate a service method with @Transactional, and the AOP proxy asks the transaction manager to begin a transaction before the method, binding the connection or EntityManager to the current thread, so all repositories in that call share it. On normal return it commits, and on a runtime exception it rolls back. Attributes control propagation, such as REQUIRED to join an existing transaction or REQUIRES_NEW to suspend it and start a new one, isolation level, timeout, readOnly and rollback rules. TransactionTemplate offers programmatic control when needed.',
    'What does readOnly = true actually do with JPA?', src),
  Q('nq-200', SF, 'EM', 'concept', 'What is the purpose of the @Transactional annotation?',
    [kp('Declares transactional boundaries on methods/classes', 'boundar*', 'method*', 'class'), kp('All DB operations in the method commit or roll back together', 'commit', 'roll* back', 'together', 'atomic*'), kp('Attributes: propagation, isolation, readOnly, timeout, rollbackFor', 'propagation', 'isolation', 'readonly', 'rollbackfor', 'timeout'), kp('Rolls back on unchecked exceptions by default, not checked', 'unchecked', 'runtimeexception', 'checked'), kp('Applies only through the proxy: public methods, no self-invocation', 'proxy', 'public', 'self invocation')],
    '@Transactional declares that a method, or all public methods of a class, should run inside a transaction, so all database work in it either commits together or rolls back together. Its attributes configure propagation, isolation, timeout, readOnly and rollback rules. By default it rolls back on RuntimeException and Error but commits on checked exceptions, unless you add rollbackFor = Exception.class. It is usually placed on service layer methods that represent a business operation, like placing an order. Because it works through a Spring proxy, it only applies to calls from outside the bean to public methods; internal calls with this do not start a transaction.',
    'Why should @Transactional usually be on the service layer, not the repository or controller?', src),
  Q('nq-201', SF, 'M', 'concept', 'How does a transaction commit or roll back?',
    [kp('Method returns normally -> commit', 'return* normally', 'commit', 'success'), kp('Runtime exception escapes -> rollback', 'runtime exception', 'unchecked', 'roll* back'), kp('Checked exception -> commit unless rollbackFor', 'checked', 'rollbackfor'), kp('Caught exceptions do not trigger rollback; setRollbackOnly / UnexpectedRollbackException', 'caught', 'swallow*', 'setrollbackonly', 'unexpectedrollbackexception'), kp('JPA flushes changes before commit', 'flush')],
    'The transactional proxy wraps the call. If the method returns normally, the proxy asks the transaction manager to commit: with JPA, Hibernate first flushes pending changes as SQL, then the database commit makes them durable. If an unchecked exception or Error escapes the method, the proxy rolls back. A checked exception commits by default unless rollbackFor includes it. If you catch an exception inside the method and swallow it, the proxy never sees it and commits, which can leave partial data, unless you call TransactionAspectSupport.currentTransactionStatus().setRollbackOnly(). And if an inner REQUIRED method marked the transaction rollback-only, the outer commit fails with UnexpectedRollbackException.',
    'What causes UnexpectedRollbackException?', src),
  Q('nq-202', SF, 'MS', 'concept', 'How does Spring\'s proxy-based transaction management work?',
    [kp('TransactionInterceptor in an AOP proxy around @Transactional beans', 'transactioninterceptor', 'proxy', 'interceptor'), kp('Reads attributes, gets/creates transaction from PlatformTransactionManager', 'attribute*', 'platformtransactionmanager', 'gettransaction'), kp('Binds resources to thread via TransactionSynchronizationManager', 'transactionsynchronizationmanager', 'thread', 'bound'), kp('Commit/rollback after invocation; propagation decides join/suspend', 'commit', 'rollback', 'propagation', 'suspend'), kp('Pitfalls: self-invocation, private methods, other threads/@Async', 'self invocation', 'private', '@async', 'other thread*')],
    'For beans with @Transactional, Spring creates a proxy whose TransactionInterceptor runs around each call. It reads the transaction attributes for the method, then calls PlatformTransactionManager.getTransaction: depending on propagation it joins an existing transaction, suspends it, or starts a new one, opening a connection or EntityManager and binding it to the current thread through TransactionSynchronizationManager. Repositories and JdbcTemplate find that thread-bound resource, so they participate automatically. After the target method returns or throws, the interceptor commits or rolls back and unbinds resources. Consequences: self-invocation and private methods are not intercepted, and work done on another thread, for example in an @Async method or a parallel stream, does not join the transaction.',
    'Why does a parallel stream inside a @Transactional method not share the transaction?', src),
  Q('nq-203', SF, 'E', 'scenario', 'Why are transactions needed when multiple database operations must succeed or fail together?',
    [kp('Atomicity: all or nothing', 'atomic*', 'all or nothing'), kp('Avoid partial updates/inconsistent state on failure', 'partial', 'inconsistent', 'failure', 'half done'), kp('Example: money transfer debit and credit; order + inventory', 'transfer', 'debit', 'credit', 'order', 'inventory'), kp('Isolation from concurrent transactions; ACID', 'isolation', 'concurren*', 'acid')],
    'Because a business operation often consists of several writes that only make sense together. In a money transfer you debit one account and credit another; if the application crashes or the second update fails after the first succeeded, money disappears. Wrapping both in a transaction gives atomicity: either both commit or both are rolled back, so the database never shows a half-done operation. Transactions also give consistency, constraints hold at commit; isolation, so other users do not see intermediate states or interfere; and durability once committed. In Spring you put @Transactional on the service method that performs, for example, saving an order, its lines and reducing stock.',
    'What happens if one of those operations is a call to an external API?', src),

  // ---------------------------------------------------------------- 16. RESTful web services and API security
  Q('nq-204', REST, 'E', 'concept', 'What are RESTful web services, and what are the key principles of REST APIs?',
    [kp('Resources identified by URIs, manipulated with HTTP methods', 'resource*', 'uri*', 'http method*'), kp('Stateless: each request carries all needed information', 'stateless', 'stateless*'), kp('Client-server, uniform interface, representations (JSON)', 'client server', 'uniform interface', 'representation*', 'json'), kp('Cacheable, layered system; HATEOAS', 'cache*', 'layered', 'hateoas'), kp('Proper status codes', 'status code*')],
    'REST, Representational State Transfer, is an architectural style for networked applications described by Roy Fielding. A RESTful service exposes resources, such as orders or customers, each identified by a URI, and clients manipulate them through representations, usually JSON, using standard HTTP methods. Key constraints: client-server separation; statelessness, so each request contains everything needed, such as the token, and the server keeps no session; cacheable responses with proper headers; a uniform interface with standard methods, status codes and media types; a layered system, so gateways and proxies can sit in between; and optionally hypermedia, HATEOAS, where responses link to related actions.',
    'Why does statelessness help scaling?', src),
  Q('nq-205', REST, 'E', 'concept', 'What HTTP methods are commonly used in REST APIs?',
    [kp('GET read, POST create', 'get', 'post'), kp('PUT replace, PATCH partial update, DELETE remove', 'put', 'patch', 'delete'), kp('HEAD and OPTIONS (CORS preflight)', 'head', 'options', 'cors'), kp('Safe and idempotent properties', 'safe', 'idempotent')],
    'GET retrieves a resource or collection and must not change state. POST creates a new resource, typically returning 201 Created with a Location header, or triggers a non-idempotent action. PUT replaces a resource entirely at a known URI, or creates it there. PATCH applies a partial update. DELETE removes a resource. HEAD is like GET without the body, for checking existence or headers, and OPTIONS describes allowed methods, used by browsers for CORS preflight requests. GET, HEAD and OPTIONS are safe; GET, PUT, DELETE, HEAD and OPTIONS are idempotent; POST and generally PATCH are not.',
    'What does idempotent mean, and why does it matter for retries?', src),
  Q('nq-206', REST, 'E', 'concept', 'What is the difference between GET, POST, PUT, PATCH, and DELETE?',
    [kp('GET reads, safe and idempotent, no body', 'get', 'read*', 'safe'), kp('POST creates, not idempotent', 'post', 'creat*', 'not idempotent'), kp('PUT replaces the whole resource, idempotent', 'put', 'replace*', 'whole'), kp('PATCH partially updates', 'patch', 'partial*'), kp('DELETE removes, idempotent; status codes 200/201/204/404', 'delete', '201', '204', '404')],
    'GET /orders/42 reads the order; it is safe, idempotent and cacheable, and has no request body. POST /orders creates a new order with a server-assigned id and returns 201 Created; repeating it creates another order, so it is not idempotent. PUT /orders/42 sends the complete representation and replaces the resource, and repeating it gives the same result, so it is idempotent; missing fields would be cleared. PATCH /orders/42 sends only the fields to change, such as the status. DELETE /orders/42 removes it, typically returning 204 No Content, and repeating it leaves it deleted, so it is idempotent, although the second call may return 404.',
    'Which status code should a successful DELETE return?', { ...src, sameAs: 'jb-199' }),
  Q('nq-207', REST, 'EM', 'concept', 'How should REST endpoints and resource names be designed?',
    [kp('Nouns, plural, not verbs: /orders, not /getOrders', 'noun*', 'plural', 'not verb*', '/orders'), kp('Hierarchy for relationships: /customers/{id}/orders', 'hierarch*', 'nested', 'sub resource*', '/customers/'), kp('HTTP methods express the action', 'http method*', 'action'), kp('Lowercase, hyphens, query params for filtering/sorting/paging', 'lowercase', 'hyphen*', 'query param*', 'filter*', 'pagination', 'paging'), kp('Versioning, consistent errors', 'version*', 'error format', 'consistent')],
    'Use nouns for resources, in plural, and let HTTP methods express actions: GET /orders and POST /orders, not /getOrders or /createOrder. Identify single items with ids, /orders/{orderId}, and express ownership with sub-resources, /customers/{id}/orders, keeping nesting shallow. Use lowercase with hyphens, like /payment-methods. Filtering, sorting and pagination belong in query parameters: /orders?status=SHIPPED&sort=createdAt,desc&page=2&size=20. For actions that do not fit CRUD, model them as resources or sub-resources, like POST /orders/{id}/cancellation. Add versioning, for example /api/v1, return consistent JSON error bodies, and document the API with OpenAPI.',
    'How would you design an endpoint for cancelling an order?', src),
  Q('nq-208', REST, 'M', 'concept', 'When should you use PATCH instead of PUT?',
    [kp('PATCH for partial updates of some fields', 'partial', 'some fields', 'few fields'), kp('PUT sends the full representation and replaces it', 'full', 'entire', 'replace*'), kp('PATCH formats: JSON Merge Patch, JSON Patch', 'merge patch', 'json patch', 'rfc 7396', 'rfc 6902'), kp('Idempotency differences and concurrency (ETag/If-Match)', 'idempot*', 'etag', 'if-match', 'concurren*')],
    'Use PATCH when the client wants to change only some fields of a resource, like updating an order status or a user phone number, without sending, or even knowing, the full representation. Use PUT when the client sends the complete new state and the server replaces the resource, which is idempotent and simple, but risks overwriting fields the client did not intend to change. PATCH bodies follow a format: JSON Merge Patch, where you send a partial JSON document and null removes a field, or JSON Patch, a list of operations like replace and add. PATCH is not guaranteed idempotent, so combine it with optimistic concurrency, ETag and If-Match headers, to avoid lost updates.',
    'How would you implement PATCH in Spring Boot safely?', src),
  Q('nq-209', REST, 'E', 'concept', 'How do you define request mappings in Spring Boot?',
    [kp('@RestController with @RequestMapping base path', '@restcontroller', '@requestmapping'), kp('@GetMapping, @PostMapping, @PutMapping, @PatchMapping, @DeleteMapping', '@getmapping', '@postmapping', '@putmapping', '@deletemapping'), kp('@PathVariable, @RequestParam, @RequestBody, @RequestHeader', '@pathvariable', '@requestparam', '@requestbody', '@requestheader'), kp('consumes/produces, validation with @Valid', 'consumes', 'produces', '@valid')],
    'Annotate a class with @RestController, which combines @Controller and @ResponseBody so return values are serialised to JSON, and give it a base path with @RequestMapping("/api/v1/orders"). Then map methods with @GetMapping("/{id}"), @PostMapping, @PutMapping("/{id}"), @PatchMapping and @DeleteMapping. Bind inputs with @PathVariable for path segments, @RequestParam for query parameters with defaults, @RequestBody for the JSON body, ideally with @Valid to trigger Bean Validation, and @RequestHeader for headers. Attributes like produces = MediaType.APPLICATION_JSON_VALUE and consumes restrict content types. Return ResponseEntity when you need to control status and headers.',
    'How do you return 201 Created with a Location header?', src),
  Q('nq-210', REST, 'M', 'scenario', 'How do you ensure that an API returns the correct HTTP response?',
    [kp('Use ResponseEntity or @ResponseStatus for correct codes', 'responseentity', '@responsestatus', 'status code*'), kp('Global error handling with @RestControllerAdvice/@ExceptionHandler', 'restcontrolleradvice', 'controlleradvice', 'exceptionhandler'), kp('Map exceptions: 400 validation, 404 not found, 409 conflict, 500', '400', '404', '409', '500'), kp('Consistent error body, Problem Details', 'problem detail*', 'error body', 'consistent'), kp('Verify with MockMvc/WebTestClient tests and API contract', 'mockmvc', 'webtestclient', 'test*', 'contract')],
    'I design the status codes explicitly and test them. Controllers return ResponseEntity, for example ResponseEntity.created(location).body(dto) for a POST, ok for reads, noContent for deletes. Errors are handled centrally in a @RestControllerAdvice with @ExceptionHandler methods that map exceptions to codes: validation failures to 400 with field errors, missing resources to 404, conflicts such as duplicates or version mismatches to 409, authentication to 401 and authorisation to 403, and unexpected errors to 500 without leaking stack traces. The error body is consistent, ideally RFC 7807 Problem Details via ProblemDetail in Spring 6. Then I verify with @WebMvcTest and MockMvc, asserting status, headers and JSON, and contract tests against the OpenAPI spec.',
    'What status should a business rule violation return?', src),
  Q('nq-211', SEC, 'M', 'concept', 'How can REST APIs and microservices be secured?',
    [kp('HTTPS/TLS everywhere', 'https', 'tls'), kp('Authentication with OAuth 2.0 / OpenID Connect and JWT', 'oauth', 'openid', 'jwt'), kp('Authorisation: roles, scopes, method security', 'authori*', 'role*', 'scope*', 'preauthorize'), kp('API gateway: rate limiting, validation, CORS', 'gateway', 'rate limit*', 'cors'), kp('Input validation, secrets management, OWASP practices, mTLS between services', 'validation', 'secret*', 'owasp', 'mtls', 'mutual tls')],
    'Defence in depth. Encrypt all traffic with TLS. Authenticate users through an identity provider with OAuth 2.0 and OpenID Connect, and have APIs accept short-lived JWT access tokens validated by Spring Security as a resource server, checking signature, issuer, audience and expiry. Authorise with roles and scopes at the gateway and again in each service, using @PreAuthorize for method security. Use an API gateway for central concerns: token validation, rate limiting, request size limits and CORS. Validate all input, use parameterised queries, return generic error messages, keep secrets in a vault, and follow the OWASP API Top 10. Between services use mTLS or service tokens through client credentials, and log security events.',
    'How do you protect against broken object level authorization (BOLA)?', src),
  Q('nq-212', SEC, 'E', 'concept', 'What is the difference between authentication and authorization?',
    [kp('Authentication verifies identity: who you are', 'identity', 'who you are', 'verif*'), kp('Authorization decides permissions: what you can do', 'permission*', 'what you can', 'access'), kp('Authentication happens first', 'first', 'before'), kp('Status codes 401 vs 403', '401', '403'), kp('Examples: login/JWT vs roles/scopes', 'login', 'jwt', 'role*', 'scope*')],
    'Authentication answers who are you: it verifies identity, for example with a username and password, a one-time code, a certificate or a valid JWT issued by the identity provider. Authorization answers what are you allowed to do: after the identity is known, it checks permissions, roles or scopes against the resource, for example only ADMIN can delete users, or a customer may only read their own orders. Authentication always comes first. In HTTP, failing authentication returns 401 Unauthorized, and an authenticated user without permission gets 403 Forbidden. In Spring Security, the authentication filter chain establishes the principal, and authorisation rules or @PreAuthorize enforce access.',
    'Which status code would you return for an expired token?', src),
  Q('nq-213', SEC, 'M', 'concept', 'What are OAuth 2.0 and JWT, and how are they used for authentication?',
    [kp('OAuth 2.0: authorization framework for delegated access tokens', 'authorization framework', 'delegat*', 'access token*'), kp('Roles: resource owner, client, authorization server, resource server; flows like authorization code + PKCE, client credentials', 'authorization server', 'resource server', 'authorization code', 'pkce', 'client credentials'), kp('OpenID Connect adds authentication (ID token)', 'openid connect', 'oidc', 'id token'), kp('JWT: signed token with header, payload claims, signature', 'header', 'payload', 'claims', 'signature', 'signed'), kp('Stateless validation; short expiry, refresh tokens, no secrets in payload', 'stateless', 'expiry', 'refresh token*', 'expire*')],
    'OAuth 2.0 is an authorization framework: it lets a client application obtain an access token from an authorization server, such as Keycloak, Okta or Azure AD, to call APIs, the resource servers, on behalf of a user or itself. Common flows are authorization code with PKCE for web and mobile apps, and client credentials for service-to-service. OAuth itself is not authentication; OpenID Connect adds that, with an ID token describing the user. A JWT is a compact token format: base64url header, payload of claims like sub, iss, aud, exp and scope, and a signature. APIs validate the signature with the issuer public keys and check claims without calling the server, so it is stateless. Keep tokens short-lived, use refresh tokens, and never put secrets in the payload, which is only encoded, not encrypted.',
    'How do you revoke a JWT before it expires?', src),
  Q('nq-214', SEC, 'MS', 'design', 'How does API Gateway-based authentication and authorization work?',
    [kp('Gateway is the single entry point; validates tokens centrally', 'single entry', 'entry point', 'validat*', 'central*'), kp('Integrates with identity provider; rejects invalid/expired tokens with 401', 'identity provider', 'idp', '401', 'expired'), kp('Coarse-grained authorization by route/scope/role', 'route*', 'scope*', 'role*', 'coarse'), kp('Forwards token or identity headers downstream; services still enforce fine-grained rules', 'forward*', 'downstream', 'header*', 'fine grained', 'zero trust'), kp('Rate limiting, logging, token relay', 'rate limit*', 'token relay')],
    'All external traffic enters through the API gateway, such as Spring Cloud Gateway, Kong, AWS API Gateway or Azure API Management. The gateway integrates with the identity provider: for each request it validates the access token signature, issuer, audience and expiry, rejecting bad tokens with 401, so invalid traffic never reaches services. It then applies coarse-grained authorisation: this route requires scope orders.write, or role ADMIN for admin paths, returning 403 otherwise. Valid requests are forwarded with the original token, token relay, or with trusted identity headers. Services still enforce fine-grained, data-level rules, such as ownership of a record, in a zero-trust model. The gateway also handles rate limiting and audit logging.',
    'Why should services not trust the gateway blindly?', src),
  Q('nq-215', SEC, 'MS', 'concept', 'How does an API Gateway validate user roles and scopes?',
    [kp('Reads claims from the validated JWT (scope/scp, roles, groups)', 'claims', 'scope', 'scp', 'roles', 'groups'), kp('Matches them against route policies/required scopes', 'route*', 'polic*', 'required'), kp('Returns 403 when insufficient', '403', 'forbidden'), kp('May call introspection endpoint for opaque tokens', 'introspect*', 'opaque'), kp('Map roles to authorities; avoid stale/overly broad scopes', 'authorit*', 'map*', 'least privilege')],
    'After validating the token signature and expiry, the gateway reads its claims: OAuth scopes in the scope or scp claim, and roles or groups in claims such as roles, realm_access or groups, depending on the identity provider. Each route has a policy, for example DELETE /api/orders/** requires scope orders.delete and role ADMIN. The gateway compares the claims with the policy and returns 403 Forbidden if they are insufficient. In Spring Cloud Gateway with Spring Security you configure this with pathMatchers and hasAuthority("SCOPE_orders.write"), mapping custom role claims to authorities with a converter. For opaque tokens, the gateway calls the authorization server introspection endpoint instead. Scopes should follow least privilege.',
    'What is the difference between a scope and a role?', src),
  Q('nq-216', SEC, 'SL', 'design', 'How do you secure communication between microservices?',
    [kp('Encrypt in transit: TLS, mutual TLS for service identity', 'mtls', 'mutual tls', 'tls'), kp('Service mesh (Istio/Linkerd) automates mTLS and policies', 'service mesh', 'istio', 'linkerd'), kp('Service-to-service tokens: OAuth client credentials or token propagation', 'client credentials', 'token propagation', 'token relay', 'service token*'), kp('Network policies, private networks, least privilege', 'network polic*', 'private network', 'least privilege', 'firewall'), kp('Secrets management and rotation', 'secret*', 'vault', 'rotation')],
    'I assume the internal network is not trusted. First, encrypt and authenticate traffic with mutual TLS, so both sides prove their identity with certificates; a service mesh like Istio or Linkerd can issue, rotate and enforce mTLS automatically, plus authorization policies saying which service may call which. Second, application-level identity: when acting for a user, propagate the user access token or exchange it; for background calls, use OAuth client credentials tokens with narrow scopes, validated by the receiving service. Third, limit reachability with Kubernetes NetworkPolicies, private subnets and security groups. Keep secrets in a vault or cloud secret manager with rotation, and log and monitor service-to-service calls.',
    'What is token exchange and when would you use it?', src),
];
